input.command:
cd /Users/thomi/Projects/entire-brain
for n in 53 54; do
  echo "############ PR #$n — latest Copilot review ############"
  gh api "repos/ashtom/entire-brain/pulls/$n/reviews" -q '[.[] | select(.user.login|test("opilot"))] | last | "[\(.state)] \(.submitted_at)\n\(.body)\n"' 2>&1 | head -20
  echo "############ PR #$n — UNRESOLVED Copilot inline threads ############"
  cnt=$(gh api graphql -f query="
  query{ repository(owner:\"ashtom\",name:\"entire-brain\"){
    pullRequest(number:$n){ reviewThreads(first:60){ nodes{ isResolved comments(first:3){ nodes{ author{login} path line body } } } } }
  }}" -q '[.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved==false) | select(.comments.nodes[0].author.login|test("opilot"))] | length' 2>&1)
  echo "unresolved Copilot threads: $cnt"
  gh api graphql -f query="
  query{ repository(owner:\"ashtom\",name:\"entire-brain\"){
    pullRequest(number:$n){ reviewThreads(first:60){ nodes{ isResolved comments(first:3){ nodes{ author{login} path line body } } } } }
  }}" -q '.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved==false) | .comments.nodes[] | select(.author.login|test("opilot")) | "--- \(.path):\(.line)\n\(.body)\n"' 2>&1
  echo
done

cd /Users/thomi/Projects/entire-brain
echo "=== confirm current mise.toml comment no longer says 'no-op'/omits CGO_LDFLAGS ==="
sed -n '585,589p' mise.toml
echo "=== resolve PR54's stale (already-addressed) Copilot threads ==="
gh api graphql -f query='
query{ repository(owner:"ashtom",name:"entire-brain"){
  pullRequest(number:54){ reviewThreads(first:60){ nodes{ id isResolved comments(first:1){ nodes{ author{login} } } } } }
}}' -q '.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved==false) | select(.comments.nodes[0].author.login|test("opilot")) | .id' 2>&1 | while read -r tid; do
  gh api graphql -f query='mutation($t:ID!){ resolveReviewThread(input:{threadId:$t}){ thread{ isResolved } } }' -F t="$tid" -q '.data.resolveReviewThread.thread.isResolved' | sed "s/^/  $tid -> resolved=/"
done

